+#include "protocol_handler.h"
+#include <stdio.h>
+#include <assert.h>
+
+int main(void) {
+    char buffer[128];
+    int result;
+
+    /* Test 1: normal case */
+    result = process_protocol_message("param_value", 11, buffer, sizeof(buffer));
+    assert(result == 0);
+    assert(strcmp(buffer, "param_value") == 0);
+    printf("Test 1 passed: normal case\n");
+
+    /* Test 2: body_len smaller than strlen */
+    result = process_protocol_message("param_value", 5, buffer, sizeof(buffer));
+    assert(result == 0);
+    assert(strcmp(buffer, "param") == 0);
+    printf("Test 2 passed: body_len smaller than strlen\n");
+
+    /* Test 3: buffer too small */
+    result = process_protocol_message("param_value", 11, buffer, 6);
+    assert(result == 0);
+    assert(strcmp(buffer, "param") == 0);
+    printf("Test 3 passed: buffer too small\n");
+
+    /* Test 4: NULL msg_body */
+    result = process_protocol_message(NULL, 11, buffer, sizeof(buffer));
+    assert(result == -1);
+    printf("Test 4 passed: NULL msg_body\n");
+
+    /* Test 5: NULL param_buffer */
+    result = process_protocol_message("test", 4, NULL, sizeof(buffer));
+    assert(result == -1);
+    printf("Test 5 passed: NULL param_buffer\n");
+
+    /* Test 6: negative body_len */
+    result = process_protocol_message("test", -1, buffer, sizeof(buffer));
+    assert(result == -1);
+    printf("Test 6 passed: negative body_len\n");
+
+    /* Test 7: zero buffer_size */
+    result = process_protocol_message("test", 4, buffer, 0);
+    assert(result == -1);
+    printf("Test 7 passed: zero buffer_size\n");
+
+    /* Test 8: non-null-terminated msg_body with body_len */
+    char raw_data[] = {'f', 'o', 'o', 'b', 'a', 'r'};
+    result = process_protocol_message(raw_data, sizeof(raw_data), buffer, sizeof(buffer));
+    assert(result == 0);
+    assert(memcmp(buffer, "foobar", 6) == 0);
+    assert(buffer[6] == '\0');
+    printf("Test 8 passed: non-null-terminated msg_body\n");
+
+    printf("\nAll tests passed!\n");
+    return 0;
+}

